        (gpu_128b_aw_gnt_ddr1 ? gpu_128b_aw.size : '0) |
        (vpu_128b_aw_gnt_ddr1 ? vpu_128b_aw.size : '0);
    assign ddr1_axi_awburst = (cpu_128b_aw_gnt_ddr1 ? cpu_128b_aw.burst : '0) |
