        (vpu_128b_aw_gnt_ddr1 ? vpu_128b_aw.lock : '0);
    assign ddr1_axi_awcache = (cpu_128b_aw_gnt_ddr1 ? cpu_128b_aw.cache : '0) |
        (dma_128b_aw_gnt_ddr1 ? dma_128b_aw.cache : '0) |
        (gpu_128b_aw_gnt_ddr1 ? gpu_128b_aw.cache : '0) |
