    assign ddr1_axi_wlast = ((cpu_128b_w_sel_ddr1 && cpu_128b_wvalid) ? cpu_128b_w.last : '0) |
        ((dma_128b_w_sel_ddr1 && dma_128b_wvalid) ? dma_128b_w.last : '0) |
        ((gpu_128b_w_sel_ddr1 && gpu_128b_wvalid) ? gpu_128b_w.last : '0) |
