    wire dma_128b_ar_gnt_ddr1 = ddr1_ar_arb_gnt_valid && (ddr1_ar_arb_gnt == 2'd1) && ddr1_ar_arb_req[1];
    wire gpu_128b_ar_gnt_ddr1 = ddr1_ar_arb_gnt_valid && (ddr1_ar_arb_gnt == 2'd2) && ddr1_ar_arb_req[2];
