        (gpu_128b_ar_gnt_ddr1 ? gpu_128b_ar.burst : '0) |
        (vpu_128b_ar_gnt_ddr1 ? vpu_128b_ar.burst : '0);
    assign ddr1_axi_arlock = (cpu_128b_ar_gnt_ddr1 ? cpu_128b_ar.lock : '0) |
