        (gpu_128b_ar_gnt_ddr1 ? gpu_128b_ar.prot : '0) |
        (vpu_128b_ar_gnt_ddr1 ? vpu_128b_ar.prot : '0);
    assign ddr1_axi_arvalid = cpu_128b_ar_gnt_ddr1 || dma_128b_ar_gnt_ddr1 || gpu_128b_ar_gnt_ddr1 || vpu_128b_ar_gnt_ddr1;

