        (gpu_128b_ar_gnt_ddr1 ? gpu_bridge_id_ar : '0) |
        (vpu_128b_ar_gnt_ddr1 ? vpu_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: sram (64b)
    // ================================================================
    // Multi-master (2 masters) → sram
